import{_ as n}from"./chunks/run-changes.BxnGjCua.js";import{_ as s,C as r,o as i,c as o,j as a,a as l,E as h,ak as d}from"./chunks/framework.sV-XtlWr.js";const k=JSON.parse('{"title":"What changed in a run","description":"","frontmatter":{"title":"What changed in a run","lang":"en-US"},"headers":[],"relativePath":"features/run-changes.md","filePath":"features/run-changes.md","lastUpdated":1788710623000}'),c={name:"features/run-changes.md"};function u(g,e,m,f,p,b){const t=r("Needs");return i(),o("div",null,[e[0]||(e[0]=a("h1",{id:"what-changed-in-a-run",tabindex:"-1"},[l("What changed in a run "),a("a",{class:"header-anchor",href:"#what-changed-in-a-run","aria-label":'Permalink to "What changed in a run"'},"​")],-1)),h(t,{reporter:""}),e[1]||(e[1]=d('<p>The <strong>Changes</strong> tab on a run compares it against <strong>one baseline</strong> and tells you what moved: which tests newly started failing, which got fixed, and what landed between the two. It&#39;s the fastest way to answer &quot;did my push break this, or was it already red?&quot;</p><h2 id="the-baseline" tabindex="-1">The baseline <a class="header-anchor" href="#the-baseline" aria-label="Permalink to &quot;The baseline&quot;">​</a></h2><p>Every section reads the <strong>same baseline</strong>, so the &quot;new failures&quot; count is computed once and used throughout. By default it&#39;s the last passing run <strong>on the same branch</strong> (see <a href="./branches.html#branch-aware-baselines">Branches</a>); pick a different run from the selector to compare against it instead. The choice is deep-linkable as <code>?baseline=&lt;runId&gt;</code>, so a link to a comparison reopens the same two runs.</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>New failures</strong> — passed in the baseline, failing here.</li><li><strong>Fixed</strong> — failed in the baseline, passing here.</li><li><strong>Still failing</strong> — failing in both.</li><li><strong>Newly flaky / passed on retry</strong> — passed here but needed a retry.</li><li><strong>Slower / faster</strong> — the ten largest duration changes each way.</li><li><strong>Commits since the baseline</strong> — the commit range, a copyable <code>git log</code> command and, when the SCM host is known, a link to the commits.</li><li><strong>Environment changes</strong> — the fields that differ, in <em>This run</em> / <em>Baseline</em> columns.</li></ul><figure><img src="'+n+'" alt="Run Changes tab showing the baseline selector, the tests that newly started failing, the ones that got fixed, and the commits landed since the baseline"><figcaption>The Changes tab on a run, read against one baseline — new failures, fixed tests, and the commits landed since.</figcaption></figure><p>Comparing two runs is also how the <a href="./ui-overview.html#test-run-detail">run comparison</a> works: select two runs on the project&#39;s Runs tab and the newer one opens on its Changes tab with the older as its baseline.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./branches.html#branch-aware-baselines">Branches</a> — why the default baseline is the same-branch run</li><li><a href="./flaky-tests.html">Flaky tests</a> — the per-project flaky, regression and spec-health signals</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a> — the failures grouped by cause</li><li><a href="./timeline-markers.html">Timeline markers</a> — annotate the trend charts with real-world events</li></ul>',9))])}const y=s(c,[["render",u]]);export{k as __pageData,y as default};
